import {L,S,Q} from './authoring.mjs';
const B=s=>{const i=s.indexOf('｜');if(i<0)throw Error('Missing bilingual text');return L(s.slice(0,i),s.slice(i+1));};
const T=s=>s.replaceAll('§',String.fromCharCode(92));
const poly=['JM02'],basic=['JM01','JM02'],extension=['extension'];
const misconceptionText={
 'height-as-slope':'Substitutes the function height for its derivative.｜以函數高度代替導數。',
 'input-as-slope':'Uses the input coordinate as the rate.｜把自變量坐標當成變化率。',
 'stationary-everywhere':'Assumes every tangent is horizontal.｜假設所有切線均水平。',
 'minimum-implies-zero-derivative':'Applies a differentiable interior-minimum theorem to a corner.｜把可微內部極小值定理套在尖角。',
 'right-side-only':'Checks only the right derivative.｜只檢查右導數。',
 'corner-implies-discontinuity':'Confuses a corner with a discontinuity.｜混淆尖角及不連續。',
 'missing-inner':'Omits the inner derivative in a composition.｜複合函數求導時漏掉內層導數。',
 'inner-only':'Keeps only the inner derivative and omits the outer rate.｜只保留內層導數，漏掉外層變化率。',
 'squared-inner':'Squares the inner coefficient instead of multiplying once.｜把內層係數平方，而非只乘一次。',
 'product-of-derivatives':'Multiplies derivatives instead of adding the two product-rule contributions.｜把導數相乘，沒有相加兩個乘積法則項。',
 'no-differentiation':'Returns the original function without differentiating.｜未求導便返回原函數。',
 'power-not-decreased':'Multiplies by the power without decreasing the exponent.｜只乘次方而未降低指數。',
 'zero-slope-minimum':'Calls every stationary point a minimum without checking signs.｜未檢查符號便把所有駐點當成極小值。',
 'zero-slope-maximum':'Calls every stationary point a maximum without checking signs.｜未檢查符號便把所有駐點當成極大值。',
 'zero-value-undefined':'Confuses a zero derivative with an undefined derivative.｜把導數為零當成導數未定義。',
 'stationary-only':'Checks only stationary points and omits interval endpoints.｜只檢查駐點，遺漏區間端點。',
 'left-end-only':'Checks only the left endpoint.｜只檢查左端點。',
 'coordinate-as-value':'Reports an input coordinate instead of the function value.｜報告自變量坐標而非函數值。',
 'minimum-is-inflection':'Confuses a minimum with a change in concavity.｜把極小值當成凹凸性轉變。',
 'zero-second-sufficient':'Treats a zero second derivative as sufficient without a sign change.｜未檢查變號便把二階導數為零視作充分條件。',
 'even-power-inflection':'Assumes an even power changes concavity at zero.｜假設偶次冪在零改變凹凸性。',
 'inflection-horizontal':'Assumes an inflection must have a horizontal tangent.｜假設拐點必有水平切線。',
 'coefficient-only':'Reports the cubic coefficient instead of the first derivative at the point.｜報告三次項係數，而非該點一階導數。',
 'zero-second-undefined':'Confuses a vanishing second derivative with a nonexistent tangent.｜把二階導數為零當成切線不存在。',
 'whole-population-denominator':'Retains the whole population after conditioning on a subgroup.｜已知子組條件後仍以全體作分母。',
 'reversed-division':'Reverses the favorable and eligible counts.｜倒轉符合及合資格數目的相除次序。',
 'decimal-place':'Moves the decimal point instead of using the conditioning ratio.｜移動小數點，而非使用條件比值。',
 'disjoint-independent':'Equates disjointness with independence.｜把互斥等同獨立。',
 'equal-independent':'Infers independence from equal marginal probabilities.｜由相等邊際概率推斷獨立。',
 'ignore-definition':'Does not compare intersection probability with the product.｜沒有比較交集概率及概率乘積。',
 'second-moment-as-variance':'Uses the second raw moment without centering.｜未中心化便把二階原點矩當方差。',
 'mean-square-minus-itself':'Subtracts the mean square from itself instead of from the second moment.｜把平均值平方自行相減，而非從二階矩減去。',
 'range-squared':'Uses squared range instead of weighted squared deviations.｜使用極差平方，而非加權離均平方。',
 'linear-scale-plus-shift':'Scales variance linearly and adds a constant shift.｜把方差線性放大並加上常數偏移。',
 'linear-scale':'Scales variance by the coefficient instead of its square.｜方差乘係數，而非係數平方。',
 'variance-plus-shift':'Adds a location shift to the variance.｜把位置偏移加入方差。',
 'fixed-n-only':'Uses fixed trial count alone to justify a binomial model.｜只因試驗次數固定便認為可用二項模型。',
 'continuous-for-discrete':'Uses an exact continuous normal model for finite counts.｜對有限計數使用精確連續正態模型。',
 'counts-equiprobable':'Assumes equally likely samples produce equally likely counts.｜假設樣本等可能便表示計數等可能。',
 'variance-as-sd':'Reads the normal variance parameter as standard deviation.｜把正態方差參數當成標準差。',
 'square-instead-root':'Squares variance instead of taking its positive square root.｜把方差平方，而非取正平方根。',
 'mean-as-sd':'Confuses the mean with the standard deviation.｜混淆平均值及標準差。',
 'reversed-residual':'Subtracts observed from predicted response.｜預測值減觀察值，倒轉殘差次序。',
 'added-values':'Adds observed and predicted responses.｜把觀察值及預測值相加。',
 'prediction-as-residual':'Reports the prediction as the residual.｜把預測值當殘差。',
 'zero-correlation-independence':'Interprets zero linear correlation as independence.｜把零線性相關解釋為獨立。',
 'correlation-as-value':'Confuses a standardized association with observed response values.｜把標準化關聯與觀察反應值混淆。',
 'negative-correlation-impossible':'Excludes negative correlations from the valid range.｜把負相關排除在有效範圍以外。',
};
function conditionText(calc){
 if(['conditional-count','choice-conditional'].includes(calc))return 'Select uniformly among the named people; the conditioning group is nonempty.｜在題述人員中等可能選取，條件組須非空。';
 if(['conditional-ratio','zero-conditioning'].includes(calc))return 'The elementary conditional ratio requires positive conditioning probability; explicitly report when this fails.｜基本條件比值要求條件概率為正；若不成立須明確指出。';
 if(['remaining-blue','two-bag-bayes','hypergeometric','hypergeometric-support','sampling-all','replacement-comparison','choice-hypergeometric','not-binomial'].includes(calc))return 'Draw uniformly from the remaining finite bag without replacement, except the explicitly compared replacement model.｜除明列放回比較模型外，從剩餘有限袋中等可能且不放回抽取。';
 if(calc==='partition')return 'Cases must form a disjoint exhaustive partition. Evaluate conditional factors only for positive-probability cells; a zero-probability cell contributes zero through its joint probability.｜分類須互斥且完備。只對概率為正的分類使用條件因子；零概率分類透過其聯合概率貢獻零。';
 if(['mixture','bayes','half-posterior'].includes(calc))return 'Cases must form a disjoint exhaustive partition; a posterior ratio requires positive evidence probability.｜分類須互斥且完備，後驗比值須有正的證據概率。';
 if(['independent-events','choice-disjoint'].includes(calc))return 'Use P(A∩B)=P(A)P(B) as the independence criterion, including the stated overlap or disjointness.｜用 P(A∩B)=P(A)P(B) 判別獨立，保留題述交集或互斥條件。';
 if(['binomial','binomial-mean','binomial-variance','reliability'].includes(calc))return 'Trials are independent, have fixed count and share the stated success probability.｜試驗獨立、次數固定，且各次成功概率相同。';
 if(['standardize','normal-table','choice-standard-deviation','continuous-point'].includes(calc))return 'The normal model has positive standard deviation; its second parameter is variance.｜正態模型標準差須為正，第二參數是方差。';
 if(calc==='independent-variance')return 'X and Y are independent with finite variances; otherwise include covariance.｜X、Y 獨立且方差有限，否則須計協方差。';
 if(['mean','variance','second-moment','constant-sum','normalize','mean-transform','variance-transform','net-gain','invalid-distribution','zero-variance','moment-impossible','risk-difference','choice-variance','choice-variance-transform'].includes(calc))return 'Finite-distribution probabilities must be nonnegative and sum to one; dependence is only as explicitly stated.｜有限分佈概率須非負且和為一，相依性只按題目明述。';
 if(['regression-slope','residual','slope-units','intercept','prediction','correlation','nonlinear-correlation','residual-sum','pairing-transfer','constant-x','causal-limitation','extrapolation','loss-transfer','choice-residual','choice-nonlinear'].includes(calc))return 'Keep the observed pairs; unique slope needs Sxx>0, correlation also Syy>0, and causal claims need a suitable design.｜保留觀察配對；唯一斜率須 Sxx>0，相關另須 Syy>0，因果聲稱須合適設計。';
 if(calc==='secant')return 'For the secant quotient h≠0; take the limit only after simplifying.｜割線差商須 h≠0，化簡後才取極限。';
 if(calc==='inverse-rate')return 'Use the branch t>0, so s=t² is invertible and its derivative is nonzero at t=2.｜使用 t>0 分支，使 s=t² 可逆且在 t=2 導數非零。';
 if(calc==='normal-square')return 'For a finite normal slope the tangent slope must be nonzero.｜法線斜率為有限值時，切線斜率須非零。';
 if(calc==='quotient-affine'||calc==='hole-inflection')return 'The rational denominator must be nonzero; excluded inputs are not points on its curve.｜有理式分母須非零，被排除自變量不是曲線上的點。';
 if(calc==='log-proof')return 'Use real x>2/3 so 3x−2>0.｜使用實數 x>2/3，使 3x−2>0。';
 if(calc==='trig-proof')return 'The trigonometric variable is measured in radians.｜三角函數自變量以弧度計。';
 if(calc==='rectangle-max')return 'Both rectangle lengths are positive; degenerate endpoints are excluded.｜長方形兩邊均為正，退化端點被排除。';
 if(calc==='open-supremum')return 'The allowed interval is open; its endpoint limit is not an attained value.｜容許區間為開區間，端點極限不是已取得的值。';
 if(['corner','corner-minimum','choice-corner'].includes(calc))return 'A derivative requires equal finite one-sided limits; an extremum itself does not require differentiability.｜導數須左右有限極限相同，極值本身不要求可微。';
 return 'Use the stated real domain and distinguish stationary candidates, attained extrema and actual concavity changes.｜使用題述實定義域，區分駐點候選、可取得極值及實際凹凸性轉變。';
}
const rubricSamples={
 'calculus-tangent':['For h≠0, [(1+h)²−1]/h=2+h; its limit is 2.｜h≠0 時，[(1+h)²−1]/h=2+h，極限為 2。','At (2,4), f′(2)=4, so y−4=4(x−2).｜在 (2,4)，f′(2)=4，故 y−4=4(x−2)。','The exact minus predicted value is h²≥0, even for negative h.｜精確值減預測值為 h²≥0，h 為負時亦然。'],
 'calculus-rules':['Both factors are differentiable; (uv)′=u′v+uv′.｜兩因子均可微，(uv)′=u′v+uv′。','For (x²+1)(x−2), derivative 2x(x−2)+(x²+1)=3x²−4x+1.｜(x²+1)(x−2) 的導數為 2x(x−2)+(x²+1)=3x²−4x+1。','ln(3x−2) needs x>2/3, not merely x≠2/3.｜ln(3x−2) 須 x>2/3，不只是 x≠2/3。'],
 'calculus-extrema':['On a closed interval I must compare included endpoints with stationary points inside it.｜閉區間須比較已包含端點及域內駐點。','For x³−3x the derivative signs are +,−,+, so the local maximum is (−1,2).｜x³−3x 的導數符號為 +、−、+，局部極大點為 (−1,2)。','On (0,1), 2x−x²<1 but tends to 1: supremum 1, no attained maximum.｜在 (0,1)，2x−x²<1 但趨向 1；上確界為 1，無可取得最大值。'],
 'calculus-inflection':['A candidate must be on the curve and concavity must change across it.｜候選點須在曲線上，且兩側凹凸性須轉變。','For x³−6x²+3x, f″=6(x−2) changes sign and f(2)=−10.｜x³−6x²+3x 的 f″=6(x−2) 變號，f(2)=−10。','At k=0, x⁴ has f″=12x²≥0 on both sides, so no inflection.｜k=0 時 x⁴ 的 f″=12x² 在兩側均非負，故無拐點。'],
 'probability-conditional':['Given music, the eligible group has 12, so probability is 5/12.｜已知音樂，合資格組有 12 人，故概率為 5/12。','The defective joint contribution is 0.09 and all flags total 0.18, so posterior is 1/2.｜次品聯合貢獻為 0.09，全部標示為 0.18，故後驗為 1/2。','If all flag contributions vanish, P(flag)=0 and the elementary posterior is undefined.｜若所有標示貢獻均為零，P(標示)=0，基本後驗未定義。'],
 'probability-moments':['For probabilities 3/4,1/4 on 0,2, E(X)=0·3/4+2·1/4=1/2.｜0、2 的概率為 3/4、1/4，E(X)=0·3/4+2·1/4=1/2。','For fair 0,2, the mean is 1 and both squared deviations are 1, so variance is 1.｜公平取 0、2，平均值為 1，兩個離均平方均為 1，故方差為 1。','If Y=1−X, X+Y=1 and variance is zero; independence is false.｜Y=1−X 時，X+Y=1，方差為零；獨立性不成立。'],
 'probability-models':['No replacement changes the next success fraction, so finite count is hypergeometric.｜不放回使下次成功比例改變，所以有限計數使用超幾何。','Two red probability from three red of five is (3/5)(2/4)=3/10.｜五件中三紅，兩紅概率為 (3/5)(2/4)=3/10。','Drawing the full bag with two reds gives X=2 surely and variance zero.｜全抽有兩紅的袋時 X 必為 2，方差為零。'],
 'statistics-regression':['Keep each pair and check Sxx=2>0 before dividing.｜保留每組配對，相除前檢查 Sxx=2>0。','For (1,1),(2,3),(3,2), Sxy=1 and Sxx=2, so slope is 1/2.｜對 (1,1)、(2,3)、(3,2)，Sxy=1、Sxx=2，故斜率為 1/2。','A symmetric y=x² scatter can have r=0, so zero correlation does not imply independence.｜對稱 y=x² 散點可有 r=0，所以零相關不表示獨立。'],
};
function R(taskType,prompt,expression,answer,method,relations,pitfall,calc,givens={},extra={}){
 const m=B(method),e=B(pitfall),kind=typeof answer==='number'?'number':'written';
 return Q(kind,'foundation',B(prompt).en,B(prompt).zh,T(expression),typeof answer==='number'?answer:B(answer),
  [m,{...B('Start from this intermediate relation.｜先從這個中間關係式入手。'),math:T(relations[0])}],
  [S(m.en,m.zh),...relations.map(x=>S('Establish and simplify this mathematical relation.','建立並化簡此數學關係式。',T(x))),S(e.en,e.zh)],
  typeof answer==='number'?L(`The requested value is ${answer}.`,`所求值為 ${answer}。`):B(answer),e,
  {taskType,examScopes:extension,conditions:[B(conditionText(calc))],
   verification:{method:'Independent calculation and derivation audit',calc,givens},
   ...(kind==='written'?{rubric:[m,B('Give the intermediate relations and explain the conclusion with its restrictions.｜列出中間關係，連同限制解釋結論。'),e]}:{}),...extra});
}
function D(taskType,prompt,expression,options,answer,misconceptions,method,relations,pitfall,calc,givens,scopes=extension){
 const raw=R(taskType,prompt,expression,0,method,relations,pitfall,calc,givens,{examScopes:scopes});
 return {...raw,kind:'choice',answer,result:B(options['ABCD'.indexOf(answer)]),choices:options.map((x,i)=>({id:'ABCD'[i],label:B(x),misconceptionId:misconceptions[i],...(misconceptions[i]==='correct'?{}:{misconception:B(misconceptionText[misconceptions[i]])})})),diagnostic:true};
}
function C(title,body,formula,motivation,derivation,conditions,counterexample,representations){return {title:B(title),body:B(body),formula:T(formula),motivation:B(motivation),derivation:derivation.map(x=>S(B(body).en,B(body).zh,T(x))),conditions:conditions.map(B),counterexample:B(counterexample),representations:representations.map(B)};}
const levels=['foundation','standard','transfer','foundation','foundation','foundation','foundation','standard','standard','standard','standard','transfer','transfer'];
function build(id,title,family,parent,source,prerequisites,objectives,concepts,errors,activities,rows,diagnostics,inquiry){
 const p=B(title),f=B(family),board=concepts.map(c=>({...c.title,math:c.formula}));
 const normalSource={documentId:'textbook-s3',section:'7.5',printedPage:83,pdfPage:88},associationSource={documentId:'textbook-s3',section:'8.1',printedPage:93,pdfPage:98};
 const questionSource=q=>id==='probability-models'&&['standardize','normal-table','continuous-point','choice-standard-deviation'].includes(q.verification.calc)?normalSource:id==='statistics-regression'&&['correlation','nonlinear-correlation','causal-limitation','choice-nonlinear'].includes(q.verification.calc)?associationSource:source;
 const decorate=(q,i,diagnostic=false)=>({...q,id:diagnostic?`diagnostic-${id}-${i+1}`:`skill-${id}-${i<3?'example':'practice'}-${i+1}`,
  kind:diagnostic?'choice':i<3?'example':q.kind,level:diagnostic?'foundation':levels[i],primarySkillIds:[id],skills:[id],difficultyReview:'reviewed',
  source:{type:'original',lessonId:id,...questionSource(q)},
  examScopeNote:q.examScopes.includes('extension')?B('This task develops the school textbook skill beyond the explicitly listed JAE syllabus topics.｜本題發展校本教材技能，超出 JAE 考綱明列範圍。'):B('This task uses elementary probability rules or polynomial calculus named in the JAE syllabus.｜本題使用 JAE 考綱列明的基本概率法則或多項式微積分。')});
 return {id,familyId:id.startsWith('calculus')?'calculus':'probability-statistics',familyTitle:f,title:p,summary:B(objectives[0]),
  bookId:'skills',chapterId:id.startsWith('calculus')?'skills-calculus':'skills-probability-statistics',source,additionalSources:id==='probability-models'?[normalSource]:id==='statistics-regression'?[associationSource]:[],parentLessonIds:parent,prerequisites,
  objectives:objectives.map(B),concepts,misconceptions:errors.map(B),questions:rows.map((q,i)=>decorate(q,i)),diagnostics:diagnostics.map((q,i)=>decorate(q,i,true)),
  teacher:{timing:[5,8,10,12,5].map((minutes,i)=>({minutes,title:B(['Predict｜預測','Build the idea｜建立概念','Guided comparison｜引導比較','Independent practice and discussion｜獨立練習與討論','Exit and next step｜課末檢核與下一步'][i]),activity:B(activities[i])})),
   prompts:[B(activities[0]),B(activities[2])],board,
   anticipated:[L(`Correct sample: ${diagnostics[0].result.en}`,`正確示例：${diagnostics[0].result.zh}`),...diagnostics.map(q=>{const wrong=q.choices.find(c=>c.id!==q.answer);return L(`Anticipated wrong response: ${wrong.label.en} — ${wrong.misconception.en}`,`預期錯答：${wrong.label.zh}；${wrong.misconception.zh}`);}),...errors.map(B)],
   followups:[...diagnostics.map(q=>L(`Follow-up: ${q.hints[0].en} Then explain why ${q.choices.find(c=>c.id!==q.answer).label.en} fails.`,`追問：${q.hints[0].zh} 再解釋 ${q.choices.find(c=>c.id!==q.answer).label.zh} 為何不成立。`)),B(inquiry.transfer)],
   remediation:[B(activities[1]),B('Return to the first example, identify the missing condition, then solve one fresh task without viewing its solution.｜返回首個例題，找出遺漏條件，再不看解答完成一道新題。')],exit:[B(activities[4])],
   rubric:[{...B('Representation and conditions｜表示法及條件'),sample:B(rubricSamples[id][0])},{...B('Connected mathematical reasoning｜連貫數學推理'),sample:B(rubricSamples[id][1])},{...B('Interpretation and boundary check｜解釋及邊界檢查'),sample:B(rubricSamples[id][2])}]},
  inquiry:{type:'skill',prediction:B(inquiry.prediction),explanation:B(inquiry.explanation),transfer:B(inquiry.transfer)}};
}
const source=(documentId,section,printedPage)=>({documentId,section,printedPage,pdfPage:printedPage+5});

const tangent=[
 R('difference-quotient','For f(x)=x² at x=1, calculate the secant slope when h=1/2.｜f(x)=x² 在 x=1，h=1/2 時求割線斜率。','f(x)=x^2;§ h=1/2',2.5,'Subtract the two function values before dividing by h.｜先把兩個函數值相減，再除以 h。',['m_h=[(1+h)^2-1]/h=2+h','m_{1/2}=5/2'],'The denominator is the input change, not the final input.｜分母是自變量改變量，不是最後的自變量。','secant',{a:1,h:.5},{examScopes:poly}),
 R('tangent-equation','Find the tangent line to y=x² at x=2.｜求 y=x² 在 x=2 的切線。','y=x^2;§ a=2','y=4x−4.｜y=4x−4。','Find the slope and the point independently.｜分別求斜率及切點。',["f'(2)=4;§ f(2)=4",'y-4=4(x-2)'],'Slope alone does not determine a line.｜只有斜率不能確定一條直線。','tangent-line',{a:2},{examScopes:poly}),
 R('inverse-rate','A sensor records s=t² and t>0. At t=2, find dt/ds and explain why it is the reciprocal of ds/dt.｜感應器記錄 s=t²，t>0。在 t=2 求 dt/ds，說明為何與 ds/dt 互為倒數。','s=t^2;§ t=2',.25,'Restrict to an invertible branch and differentiate t=√s.｜先限制在可逆分支，再對 t=√s 求導。',['ds/dt=2t=4','dt/ds=1/(2§sqrt{s})=1/4'],'A reciprocal derivative needs a nonzero derivative and a local inverse.｜倒數關係要求導數非零及局部反函數。','inverse-rate',{t:2},{examScopes:poly}),
 R('instantaneous-rate','Find f′(−2) for f(x)=x².｜f(x)=x²，求 f′(−2)。','f(x)=x^2;§ a=-2',-4,'Take the limit of the difference quotient.｜取差商的極限。', ['[(-2+h)^2-4]/h=-4+h',"f'(-2)=-4"],'A negative slope is a direction, not a negative distance.｜負斜率描述方向，不是負距離。','derivative-square',{a:-2},{examScopes:poly}),
 R('average-rate','Position is s(t)=t². Find the average velocity from t=1 to t=3.｜位置 s(t)=t²，求 t=1 至 t=3 的平均速度。','s(t)=t^2;§ 1§le t§le3',4,'Divide the position change by the time change.｜位置改變量除以時間改變量。',['v_{avg}=(9-1)/(3-1)','v_{avg}=4'],'Average velocity over an interval is not automatically the velocity at its first endpoint.｜區間平均速度不必等於起點瞬時速度。','average-square',{a:1,b:3},{examScopes:poly}),
 R('point-versus-slope','For f(x)=x³ at x=2, find the tangent slope rather than the height.｜f(x)=x³ 在 x=2，求切線斜率而非高度。','f(x)=x^3;§ a=2',12,'Differentiate before substituting.｜先求導，再代入。',["f'(x)=3x^2","f'(2)=12;§ f(2)=8"],'Function value and derivative value answer different questions.｜函數值及導數值回答不同問題。','derivative-cube',{a:2},{examScopes:poly}),
 R('corner-test','Does |x| have a finite derivative at zero? Justify with one-sided quotients.｜|x| 在零是否有有限導數？用左右差商說明。','f(x)=|x|;§ a=0','No: the one-sided slopes are −1 and 1.｜沒有；左右斜率為 −1 及 1。','Keep the sign of h when removing the absolute value.｜去除絕對值時保留 h 的符號。',['|h|/h=-1§ (h<0)','|h|/h=1§ (h>0)'],'Continuity does not supply a common two-sided derivative.｜連續不能保證左右導數相同。','corner',{}, {examScopes:poly}),
 R('normal-line','For y=x² at x=1, find the slope of the normal.｜y=x² 在 x=1，求法線斜率。','y=x^2;§ a=1',-.5,'Use the perpendicular-line slope relation after finding the tangent slope.｜先求切線斜率，再使用垂直直線的斜率關係。',["m_T=f'(1)=2",'m_N=-1/m_T=-1/2'],'Taking only the negative does not make the slopes perpendicular.｜只取相反數不能使斜率互相垂直。','normal-square',{a:1},{examScopes:poly}),
 R('tangent-through-point','Find all tangents to y=x² that pass through (0,−4).｜求經過 (0,−4) 且與 y=x² 相切的所有直線。','y=x^2;§ P=(0,-4)','y=4x−4 and y=−4x−4.｜y=4x−4 及 y=−4x−4。','Let a denote the unknown contact point, not the external point.｜用 a 表示未知切點，不是外部點。',['y=2ax-a^2;§ -4=-a^2','a=§pm2;§ y=§pm4x-4'],'The given point need not lie on the curve.｜給定點不必位於曲線上。','tangents-external',{intercept:-4},{examScopes:poly}),
 R('zero-slope-normal','Describe the tangent and normal to y=x² at zero.｜描述 y=x² 在零的切線及法線。','y=x^2;§ a=0','Tangent y=0; normal x=0.｜切線 y=0；法線 x=0。','Treat a vertical normal with its equation, not a finite slope.｜用方程表示垂直法線，不要指定有限斜率。',["f'(0)=0",'T:y=0;§ N:x=0'],'The expression −1/0 is undefined; the normal is still a valid vertical line.｜−1/0 未定義，但法線仍是有效的垂直直線。','vertical-normal',{}, {examScopes:poly}),
 R('measured-rate','For f(2)=7 and f′(2)=−3, use a tangent approximation for f(2.04).｜已知 f(2)=7、f′(2)=−3，用切線近似 f(2.04)。',"f(2)=7;§ f'(2)=-3",6.88,'Use the small input increment, retaining the derivative sign.｜使用小的自變量增量，保留導數正負號。',['§Delta x=0.04','f(2.04)§approx7-3(0.04)=6.88'],'The approximation is local and is not an exact value without further information.｜此為局部近似；沒有額外資料時不是精確值。','linear-approx',{value:7,slope:-3,delta:.04},{examScopes:poly}),
 R('parameter-tangency','Which values of c make y=x+c tangent to y=x²? Explain uniqueness.｜哪些 c 使 y=x+c 與 y=x² 相切？說明為何唯一。','x^2=x+c','c=−1/4, with contact at x=1/2.｜c=−1/4，切點橫坐標為 1/2。','Translate tangency into a repeated intersection root.｜把相切轉成重複交點根。',['x^2-x-c=0;§ §Delta=1+4c','§Delta=0§implies c=-1/4;§ x=1/2'],'A line can cross a curve while sharing some nearby slope; the contact condition is essential.｜附近斜率相同不代表相切，仍須符合接觸條件。','parameter-tangent',{}, {examScopes:poly}),
 R('tangent-local-error','For y=x², prove the tangent approximation at a never overestimates f(a+h), and find the error at h=−0.2.｜對 y=x²，證明在 a 的切線近似總不高估 f(a+h)，並求 h=−0.2 時的誤差。','f(x)=x^2;§ h=-0.2',.04,'Subtract the tangent prediction from the exact function value.｜用精確函數值減去切線預測。',['(a+h)^2-[a^2+2ah]=h^2§ge0','h=-0.2§implies h^2=0.04'],'The error is nonnegative for both signs of h; its first-order term cancels.｜h 正負兩種情況的誤差均非負；一次項相消。','tangent-error',{h:-.2},{examScopes:poly}),
];
